        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_expr():
        val = parse_term()
        while peek()[0] in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            if op == '+':
                val = val + rhs
            else:
                val = val - rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek()[0] in ('*', '/'):
            op = advance()[0]
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                val = trunc_div(val, rhs)
        return val

    def parse_factor():
        if peek()[0] == '-':
            advance()
            return -parse_factor()
        return parse_atom()

    def parse_atom():
        tok_type, tok_val = peek()
        if tok_type == 'NUM':
            advance()
            return tok_val
        if tok_type == '(':
            advance()
            val = parse_expr()
            if peek()[0] != ')':
                raise ValueError("Expected ')'")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok_type}")

    result = parse_expr()
    return result

